using Microsoft.EntityFrameworkCore;

namespace MyApp.Services;

public class OrderProcessingService : BackgroundService
{
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<OrderProcessingService> _logger;
    private readonly TimeSpan _interval = TimeSpan.FromSeconds(30);

    public OrderProcessingService(
        IServiceScopeFactory scopeFactory,
        ILogger<OrderProcessingService> logger)
    {
        _scopeFactory = scopeFactory;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("OrderProcessingService started.");

        using var timer = new PeriodicTimer(_interval);

        while (!stoppingToken.IsCancellationRequested &&
               await timer.WaitForNextTickAsync(stoppingToken))
        {
            try
            {
                await ProcessPendingOrdersAsync(stoppingToken);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                // Log and continue — don't let one failure kill the service
                _logger.LogError(ex, "Error processing pending orders.");
            }
        }

        _logger.LogInformation("OrderProcessingService stopped.");
    }

    private async Task ProcessPendingOrdersAsync(CancellationToken ct)
    {
        // Create a new scope per iteration so EF Core gets a fresh DbContext
        using var scope = _scopeFactory.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

        var pendingOrders = await db.Orders
            .Where(o => o.Status == OrderStatus.Pending)
            .ToListAsync(ct);

        if (pendingOrders.Count == 0)
            return;

        _logger.LogInformation("Processing {Count} pending order(s).", pendingOrders.Count);

        foreach (var order in pendingOrders)
        {
            try
            {
                // --- Replace with your real processing logic ---
                order.Status = OrderStatus.Completed;
                order.ProcessedAt = DateTime.UtcNow;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process order {OrderId}.", order.Id);
                order.Status = OrderStatus.Failed;
            }
        }

        await db.SaveChangesAsync(ct);
    }
}

